def _repolish(w: QWidget) -> None:
    w.style().unpolish(w)
    w.style().polish(w)


def _clear(lay) -> None:
    while lay.count():
        it = lay.takeAt(0)
        w = it.widget()
        if w is not None:
            w.hide()
            w.setParent(None)
            w.deleteLater()
        elif it.layout() is not None:
            _clear(it.layout())


