    lines.push(line);
    ids.push(n.id);
    used += line.length;
  }
  if (!lines.length) return { text: '', ids: [] };
  // How many sessions each note reached, so the tally on the Memory page has a denominator.
  const d = load(cwd);
  for (const n of d.notes) if (ids.includes(n.id)) n.handed = (n.handed || 0) + 1;
