    d.distills = d.distills || {};
    d.distills[session.id] = { at: Date.now(), added: added.length };
    trim(d);
    save(cwd);
    log('memory distilled', session.id, added.length, 'notes');
    return { added: added.map(withStanding) };
  })().finally(() => inflight.delete(session.id));
