    out.me.sort((a, b) => Number(Boolean(a.conflict)) - Number(Boolean(b.conflict)) || Number(cardState(b, rt[b.id], now) === 'prompt') - Number(cardState(a, rt[a.id], now) === 'prompt') || (b.lastModified || 0) - (a.lastModified || 0));
