        setUi({ returnTo: 'board', ...(cardState(s, useStore.getState().rt[id]) === 'review' ? { panel: true, panelTab: 'changes' as const } : {}) });
        openSession(id);
      } else if (action === 'approve') {
        await decideCard(id, 'approve');
        nextNeeds();
