// Shared client-side types for data coming from the Pilcrow server.

export type SessionStatus = 'idle' | 'starting' | 'running' | 'requires_action' | 'error' | 'stopped';
/** Claude has the session in hand: starting, working, or waiting on the person in the middle of a turn. */
export const isBusy = (status: string | undefined) => status === 'running' || status === 'starting' || status === 'requires_action';
/** Claude is producing something right now: busy, and not waiting on the person. */
export const isWorking = (status: string | undefined) => status === 'running' || status === 'starting';
export type PermissionMode = 'default' | 'acceptEdits' | 'plan' | 'bypassPermissions' | 'dontAsk' | 'auto';
export type Effort = '' | 'low' | 'medium' | 'high' | 'xhigh' | 'max';

export interface Worktree {
  path: string;
  branch: string;
  base: string;
  repoRoot: string;
}

export interface SessionSummary {
  id: string;
  title: string;
  firstPrompt?: string;
  cwd: string;
  project: string;
  gitBranch?: string | null;
  lastModified?: number;
  createdAt?: number;
  archived: boolean;
  pinned: boolean;
  worktree: Worktree | null;
  status: SessionStatus;
  live: boolean;
  pending?: number;
  /** Started by a schedule; such sessions live in the inbox rather than the sidebar. */
  scheduled?: { id: string; name: string; at: number; manual?: boolean } | null;
  /** A run of a dispatch job (or its report session); reachable from the job's view. */
  dispatch?: { jobId: string; runId: string | null; name: string; target: string } | null;
  /** A helper of another session (HELPERS.md): nested under its lead in the sidebar. */
  helper?: { leadId: string; name: string; state: HelperStateName | null } | null;
  /** A session that has started helpers. */
  lead?: { since: number; count: number } | null;
  // ---- workboard (docs/WORKBOARD.md). All optional; a plain conversation has none of them.
  /** Two or three sentences on what the work is and when it is done. A session with one is a card. */
  intent?: string;
  /** When Claude's last turn ended. */
  turnEnd?: number;
  /** The turn end you last reviewed; equal to `turnEnd` means this turn has been dealt with. */
  reviewedTurn?: number;
  /** Your decisions on the card, oldest first. */
  decisions?: Decision[];
  costUsd?: number;
  wait?: WaitCondition | null;
  report?: HandoffReport | null;
  /** Held until Claude is below the concurrency limit; the text is what will be sent. */
  queued?: { text: string; at: number } | null;
  /** Only on the card the board makes for a contradicted note in project memory (docs/PLAYBOOK.md §4). */
  conflict?: MemoryConflict;
}

/** Approvals and send-backs on the workboard for a project, apart for sessions that had notes and sessions that had none. */
export interface MemoryStats {
  withNotes: { approve: number; reject: number };
  without: { approve: number; reject: number };
}

/** A note in project memory that a correction of yours contradicted; it waits on the board to be kept or forgotten. */
export interface MemoryConflict {
  id: string;
  cwd: string;
  text: string;
  standing: 'confirmed' | 'fresh' | 'retired';
  at: number;
  correction: string;
  sessionId: string | null;
  sessionTitle: string | null;
  /** The note the correction was written as instead, when there is one. */
  replacement: { id: string; text: string } | null;
}

export type DecisionKind = 'approve' | 'reject' | 'answer' | 'park' | 'wait' | 'wake' | 'stop' | 'start' | 'steer';
export interface Decision {
  at: number;
